INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65017577', 65017577, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior  Perancangan dan Pengelolaan  Materi Desain Komunikasi Visual  Manajemen Risiko  Pembangunan Nasional (MRPN)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 81180000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Lingkup kegiatan Jasa Konsultan Junior Perancangan dan Pengelolaan Materi Desain Komunikasi Visual Manajemen Risiko Pembangunan Nasional (MRPN) meliputi pemberian dukungan teknis dalam penyusunan, pengembangan, dan penyempurnaan materi desain komunikasi visual yang berkaitan dengan kebijakan, pedoman, sistem, dan instrumen Manajemen Risiko Pembangunan Nasional yang dilaksanakan oleh Direktorat Sistem dan Manajemen Risiko. Kegiatan ini mencakup pembuatan infografis, ilustrasi, materi presentasi, serta konten visual untuk publikasi digital dan cetak, dengan memperhatikan ketepatan substansi, kaidah desain komunikasi visual, serta keselarasan dengan standar identitas dan kebutuhan kelembagaan, guna mendukung kegiatan sosialisasi, koordinasi, dan advokasi penerapan manajemen risiko pembangunan.', 'Output kegiatan Jasa Konsultan Junior Perancangan dan Pengelolaan Materi Desain Komunikasi Visual Manajemen Risiko Pembangunan Nasional (MRPN) meliputi tersusunnya dokumen pendukung desain komunikasi visual yang terencana, konsisten, dan terdokumentasi, tersusunnya materi desain komunikasi visual yang selaras dengan standar identitas kelembagaan, serta terdokumentasikannya hasil pekerjaan dalam bentuk Laporan Perancangan dan Pengelolaan Materi Desain Komunikasi Visual Manajemen Risiko Pembangunan Nasional (MRPN) dan arsip digital sebagai bentuk pertanggungjawaban pelaksanaan kegiatan pengadaan. Adapun penjelasan keluaran setiap terminnya sebagai berikut: No Periode Keluaran per Termin 1 Termin 1 Laporan strategi komunikasi visual instansi 2 Termin 2 Laporan narasi dan konsep visual terpadu 3 Termin 3 Laporan analisis perilaku dan persepsi audiens 4 Termin 4 Laporan pedoman keselarasan pesan verbal dan visual 5 Termin 5 Laporan evaluasi dampak komunikasi visual 6 Termin 6 Laporan Perancangan dan Pengelolaan Materi Desain Komunikasi Visual Manajemen Risiko Pembangunan Nasional (MRPN)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1912346);
