INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65017628', 65017628, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Jasa Konsultan Junior Penyusunan Dokumen Perencanaan Program Pendampingan Sanitasi Keg. Koordinasi Program Swasembada Air (Air Minum dan Sanitasi Nasional)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 97000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', 'Pekerjaan Tenaga Ahli Muda Perencanaan Program Sanitasi dalam kegiatan Koordinasi Program Swasembada Air (Air Minum dan Sanitasi Nasional) dengan lingkup pekerjaan: 1. Mendukung program pendampingan sanitasi (Percepatan Pembangunan Sanitasi Permukiman/PPSP) kepada Pemerintah Daerah; 2. Memfasilitasi pemerintah daerah dalam penyusunan/pemutakhiran dokumen perencanaan sanitasi seperti SSK (Strategi Sanitasi Kota/Kabupaten); 3. Menelaah efektivitas program pendampingan dan bottleneck yang terjadi; 4. Membantu penyusunan materi pendalaman dan pengembangan kebijakan, program serta kegiatan di bidang sanitasi untuk pemerintah daerah; 5. Mendukung pemetaan gap kapasitas dan pelaksanaan peningkatan kapasitas bagi pemerintah daerah; dan 6. Menyusun laporan bulanan Jasa Konsultan Junior Perencanaan Program Pendampingan Sanitasi.', '1. Pendidikan minimal S1 jurusan perencanaan wilayah dan kota/planologi/teknik lingkungan/manajemen infrastruktur/ekonomi pembangunan; 2. Memiliki pengalaman kerja di bidang Perumahan dan Kawasan Permukiman minimal 2 tahun, pengalaman di bidang air minum atau sanitasi merupakan nilai tambah (dibuktikan dengan kontrak); 3. Memiliki pengalaman dalam melakukan perencanaan program dan kegiatan di lingkup pemerintahan; dan 4. Memiliki pengalaman dalam berkoordinasi dengan Kementerian/Lembaga dan Pemerintah Daerah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1913424);
