INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65125781', 65125781, 'analyze_legacy', 'Kab. Mahakam Ulu', 'kabkota', 'Sekretariat DPRD', 'Belanja Sewa Kendaraan Bermotor Beroda Dua kegiatan Reses masa Sidang I', 'Jasa Lainnya', 'Pengadaan Langsung', 'Kalimantan Timur, Mahakam Ulu (Kab.)', 40000000, 'February 2026', 'APBD', 1, 1, '1 Paket', 'Pekerjaan ini merupakan sewa kendaraan bermotor beroda dua dalam rangka memfasilitasi mobilitas masyarakat pada pelaksanaan kegiatan Reses DPRD Masa Sidang I, guna mendukung kehadiran dan partisipasi masyarakat dalam kegiatan reses di daerah pemilihan.', 'Penyediaan jasa sewa kendaraan bermotor beroda dua untuk mendukung mobilitas masyarakat peserta kegiatan Reses DPRD Masa Sidang I, dengan kondisi kendaraan laik jalan, aman digunakan, dan disesuaikan dengan kebutuhan kegiatan.', 40000000, 'high', 'Pengadaan sewa kendaraan roda dua untuk memfasilitasi mobilitas masyarakat peserta reses DPRD terindikasi kurang relevan dengan penggunaan anggaran publik yang lazim. Fasilitasi transportasi warga untuk menghadiri kegiatan reses berpotensi menjadi bentuk pembiayaan yang tidak proporsional terhadap fungsi penyerapan aspirasi, sehingga seluruh nilai paket layak dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 1913803);
