INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65127864', 65127864, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA BANDAR UDARA RAHADI OESMAN DI KETAPANG', 'Kendaraan PKP-PK', 'Barang', 'Penunjukan Langsung', 'Kalimantan Barat, Ketapang (Kab.)', 100000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '( 4, Unit, @ 25000000 )', 'Belanja pemeliharaan peralatan dan mesin Kendaraan PKP-PK berupa kegiatan perawatan rutin, pemeriksaan, servis berkala, dan perbaikan komponen kendaraan pemadam dan penyelamatan untuk menjaga kesiapan operasional, keandalan mesin, serta keselamatan penggunaan, meliputi servis mesin, sistem pompa, kelistrikan, rangka/karoseri, dan perlengkapan pendukung agar kendaraan selalu dalam kondisi siap pakai.', 'Pekerjaan mencakup servis berkala kendaraan meliputi penggantian oli mesin, filter, pelumas, pengecekan sistem bahan bakar, pendingin, rem, kopling, transmisi, suspensi, kemudi, ban, dan aki, serta pemeriksaan sistem kelistrikan dan panel kontrol. Termasuk perawatan dan pengujian sistem pompa pemadam, tangki air/busa, selang, nozzle, valve, monitor, serta peralatan penyelamatan lainnya, pembersihan unit, pelumasan komponen bergerak, kalibrasi ringan, serta perbaikan atau penggantian suku cadang minor yang aus/rusak. Pelaksanaan dilakukan oleh teknisi kompeten dengan menerapkan K3, menggunakan suku cadang standar pabrikan, serta dilengkapi pengujian fungsi (running test) untuk memastikan kendaraan dan peralatan dalam kondisi andal, aman, dan siap operasi setiap saat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1919885);
